WITH filtered AS (SELECT *, DATE_FORMAT(event_time, 'yyyy-MM-dd') event_time_label, INITCAP(TRIM(page)) page_title, COALESCE(page, 'OTHER') resolved_page FROM web_events WHERE event_time > DATE '2023-09-28') SELECT session_id, DATE_TRUNC('WEEK', event_time) AS week_start, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS span_minutes, APPROX_PERCENTILE(duration_sec, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_quartiles, COUNT(CASE WHEN event_type = 'click' THEN 1 END) AS click_count, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, MAX(event_time) AS ended_at, GROUPING(session_id) AS grouping_level FROM filtered GROUP BY CUBE (session_id, DATE_TRUNC('WEEK', event_time)) HAVING span_minutes >= 0 ORDER BY session_id DESC
